#!/usr/bin/env bash
set -euo pipefail
cd "$(dirname "$0")";test -f .env||{ echo 'Copy .env.example to .env.';exit 1;};test -d backend/node_modules -a -d frontend/node_modules||{ echo 'Run scripts/bootstrap.sh first.';exit 1;};set -a;source .env;set +a;[[ "$BACKEND_PORT" =~ ^[0-9]+$ && "$FRONTEND_PORT" =~ ^[0-9]+$ && "$BACKEND_PORT" != "$FRONTEND_PORT" ]]||{ echo 'Distinct numeric backend/frontend ports are required.' >&2;exit 2;};for assigned_port in "$BACKEND_PORT" "$FRONTEND_PORT";do lsof -tiTCP:"$assigned_port" -sTCP:LISTEN >/dev/null 2>&1&&{ echo "Assigned port $assigned_port is already in use; no process was stopped." >&2;exit 1;}||true;done;node backend/server.js& backend_pid=$!;npm --prefix frontend run dev -- --host 127.0.0.1 --port "$FRONTEND_PORT" --strictPort& frontend_pid=$!;cleanup(){ kill "$backend_pid" "$frontend_pid" 2>/dev/null||true;};trap cleanup EXIT INT TERM;wait "$backend_pid" "$frontend_pid"
